27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "postcode")
47	    @Pattern(regexp = "^[0-9]{4}$", message = "Postcode must be 4 digits")
48	    private String postcode;
49	
50	    @Column(name = "telephone")
51	    @NotEmpty
52	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
53	    private String telephone;
54	
55	    @Column(name = "email")
56	    private String email;
57	
58	    @Column(name = "registration_date")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "birth_date")
62	    private LocalDate birthDate;
63	
64	    @Column(name = "customer_code")
65	    private String customerCode;
66	
67	    @Column(name = "household_id")
68	    private String householdId;
69	
70	    @Column(name = "identity_key")
71	    private String identityKey;
72	
73	    @Column(name = "namesake_count")
74	    private Integer namesakeCount;
75	
76	    @Column(name = "household_member_count")
77	    private Integer householdMemberCount;
78	
79	    @Column(name = "membership_number")
80	    private String membershipNumber;
81	
82	    @Column(name = "possible_duplicate")
83	    private Boolean possibleDuplicate;
84	
85	    @Column(name = "possible_duplicate_of")
86	    private Integer possibleDuplicateOf;
87	
88	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
89	    private Set<Pet> pets;
90	
91	    public String getAddress() {
92	        return this.address;
93	    }
94	
95	    public void setAddress(String address) {
96	        this.address = address;
97	    }
98	
99	    public String getCity() {
100	        return this.city;
101	    }
102	
103	    public void setCity(String city) {
104	        this.city = city;
105	    }
106	
107	    public String getPostcode() {
108	        return this.postcode;
109	    }
110	
111	    public void setPostcode(String postcode) {
112	        this.postcode = postcode;
113	    }
114	
115	    public String getTelephone() {
116	        return this.telephone;
117	    }
118	
119	    public void setTelephone(String telephone) {
120	        this.telephone = telephone;
121	    }
122	
123	    public String getEmail() {
124	        return this.email;
125	    }
126	
127	    public void setEmail(String email) {
