187	    public String getMembershipNumber() {
188	        return this.membershipNumber;
189	    }
190	
191	    public void setMembershipNumber(String membershipNumber) {
192	        this.membershipNumber = membershipNumber;
193	    }
194	
195	    public Boolean getPossibleDuplicate() {
196	        return this.possibleDuplicate;
197	    }
198	
199	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
200	        this.possibleDuplicate = possibleDuplicate;
201	    }
202	
203	    public Integer getPossibleDuplicateOf() {
204	        return this.possibleDuplicateOf;
205	    }
