211	    /**
212	     * The owner's membership points, derived on read: they start at 0, add 2 when an email is
213	     * present, add 1 when {@link #namesakeCount} is 0, add 2 for a household of 3 or more
214	     * ({@link #householdMemberCount}), and add 3 for tenure over 365 days (whole days from
215	     * {@link #registrationDate} to today).
216	     */
217	    @Transient
218	    public Integer getMembershipPoints() {
219	        return membershipPoints(this.email, this.namesakeCount, this.householdMemberCount,
220	            this.registrationDate);
221	    }
222	
223	    /**
224	     * The owner's numeric membership level, derived on read from {@link #getMembershipPoints()}:
225	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
226	     */
227	    @Transient
228	    public Integer getMembershipLevel() {
229	        return membershipLevel(getMembershipPoints());
230	    }
231	
232	    /** The membership points derived from the given factors: they start at 0, add 2 when
233	     *  {@code email} is present, add 1 when {@code namesakeCount} is 0, add 2 for a household of 3 or
234	     *  more ({@code householdMemberCount}), and add 3 for tenure over 365 days (whole days from
235	     *  {@code registrationDate} to today). */
236	    private static int membershipPoints(String email, Integer namesakeCount,
237	            Integer householdMemberCount, LocalDate registrationDate) {
238	        int points = 0;
239	        if (email != null && !email.isBlank()) {
240	            points += 2;
241	        }
242	        if (namesakeCount != null && namesakeCount == 0) {
243	            points += 1;
244	        }
245	        if (householdMemberCount != null && householdMemberCount >= 3) {
246	            points += 2;
247	        }
248	        if (registrationDate != null
249	                && java.time.temporal.ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > 365) {
250	            points += 3;
251	        }
252	        return points;
253	    }
254	
255	    /** The numeric membership level (1-4) mapped from membership points: 1 for 0-1 points, 2 for
256	     *  2-3, 3 for 4-5, and 4 for 6 or more. */
257	    private static int membershipLevel(int points) {
258	        if (points >= 6) {
259	            return 4;
260	        }
261	        if (points >= 4) {
262	            return 3;
263	        }
264	        if (points >= 2) {
265	            return 2;
266	        }
267	        return 1;
268	    }
269	
270	    /**
271	     * The owner's preferred contact channel, derived on read: {@code "EMAIL"} when an email is
272	     * present, otherwise {@code "PHONE"}.
273	     */
274	    @Transient
275	    public String getContactPreference() {
276	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
277	    }
278	
279	    /**
280	     * The owner's age band, derived on read from the {@link #birthDate} relative to the
281	     * {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18 to 64, and
282	     * {@code "SENIOR"} at 65 or over. Returns {@code null} when no birth date (or no registration
283	     * date to measure against) is available.
284	     */
285	    @Transient
286	    public String getAgeBand() {
287	        if (this.birthDate == null || this.registrationDate == null) {
288	            return null;
289	        }
290	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
291	        if (age < 18) {
292	            return "MINOR";
293	        }
294	        if (age < 65) {
295	            return "ADULT";
296	        }
297	        return "SENIOR";
298	    }
299	
300	    /**
301	     * The single Luhn check digit (0-9) computed over the decimal digits contained in the
302	     * {@link #customerCode}, derived on read.
303	     */
304	    @Transient
305	    public Integer getCheckDigit() {
306	        return luhnCheckDigit(this.customerCode);
307	    }
308	
309	    /** Region -> inclusive 4-digit postcode range {low, high}, used to derive the region from the
310	     *  postcode ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
311	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
312	        "NSW", new int[] {2000, 2099},
313	        "VIC", new int[] {3000, 3099},
314	        "QLD", new int[] {4000, 4099});
315	
316	    /**
317	     * The owner's region, derived on read. The postcode is preferred: a 4-digit postcode falling in a
318	     * known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}) yields
319	     * that region. When the postcode is absent or in no known range, it falls back to the fixed
320	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
321	     * Returns {@code "UNKNOWN"} when neither source resolves a region.
322	     */
323	    @Transient
324	    public String getRegion() {
325	        String byPostcode = regionForPostcode(this.postcode);
326	        if (byPostcode != null) {
327	            return byPostcode;
328	        }
329	        if ("Sydney".equals(this.city)) {
330	            return "NSW";
331	        }
332	        if ("Melbourne".equals(this.city)) {
333	            return "VIC";
334	        }
335	        if ("Brisbane".equals(this.city)) {
336	            return "QLD";
337	        }
338	        return "UNKNOWN";
339	    }
340	
341	    /**
342	     * The owner's locality, derived on read from the region-and-hash {@link #getCustomerCode()
343	     * customer code}: the region segment before the first '-' of the customer code
344	     * ('<REGION>-<HASH8>'). Falls back to the owner's {@link #getRegion() region} when no customer
345	     * code has been assigned yet.
346	     */
347	    @Transient
348	    public String getLocality() {
349	        if (this.customerCode != null) {
350	            int dash = this.customerCode.indexOf('-');
351	            if (dash > 0) {
352	                return this.customerCode.substring(0, dash);
353	            }
354	        }
355	        return getRegion();
356	    }
357	
358	    /** Region -> IANA timezone name, the fixed region-to-timezone table ({@code NSW ->
359	     *  Australia/Sydney}, {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). */
360	    private static final Map<String, String> REGION_TIMEZONES = Map.of(
361	        "NSW", "Australia/Sydney",
362	        "VIC", "Australia/Melbourne",
363	        "QLD", "Australia/Brisbane");
364	
365	    /**
366	     * The owner's timezone, derived on read as the IANA name for the owner's
367	     * {@link #getLocality() locality/region} via the fixed region-to-timezone table
368	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
369	     * {@code QLD -> Australia/Brisbane}). Returns {@code null} when the region carries no entry in
370	     * the table (e.g. {@code UNKNOWN}).
371	     */
372	    @Transient
373	    public String getTimezone() {
374	        return timezoneForRegion(getLocality());
375	    }
376	
377	    /** The IANA timezone name for {@code region} via the fixed region-to-timezone table, or
378	     *  {@code null} when the region carries no entry ({@code NSW -> Australia/Sydney},
379	     *  {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). */
380	    public static String timezoneForRegion(String region) {
381	        return REGION_TIMEZONES.get(region);
382	    }
383	
384	    /** The inclusive 4-digit postcode {@code {low, high}} range for {@code region}, or {@code null} when
385	     *  the region carries no range rule (i.e. {@code UNKNOWN} or any region absent from the table:
386	     *  {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
387	    public static int[] postcodeRangeForRegion(String region) {
388	        return REGION_POSTCODE_RANGES.get(region);
389	    }
390	
391	    /** The region whose postcode range contains {@code postcode}, or {@code null} when the postcode is
392	     *  absent, not a 4-digit value, or in no known range. */
393	    private static String regionForPostcode(String postcode) {
394	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
395	            return null;
396	        }
397	        int value = Integer.parseInt(postcode);
398	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
399	            int[] range = entry.getValue();
400	            if (value >= range[0] && value <= range[1]) {
401	                return entry.getKey();
402	            }
403	        }
404	        return null;
405	    }
406	
407	    /** Telephone country code -> the national-number length it requires ({@code +61} Australia => 9
408	     *  digits, {@code +1} NANP => 10), used to derive telephone values from the stored E.164 number.
409	     *  The country codes here carry no conflicting prefixes ({@code +61} does not start with
410	     *  {@code +1}), so a number matches at most one. */
411	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
412	        "+61", 9, "+1", 10);
413	
414	    /**
415	     * The stored E.164 {@link #telephone} formatted for humans, derived on read: the country code, a
416	     * space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}). Falls back
417	     * to the raw value when it is {@code null} or begins with no recognised country code.
418	     */
419	    @Transient
420	    public String getTelephoneDisplay() {
421	        if (this.telephone == null) {
422	            return null;
423	        }
424	        String countryCode = countryCodeOf(this.telephone);
425	        if (countryCode == null) {
426	            return this.telephone;
427	        }
428	        String national = this.telephone.substring(countryCode.length());
429	        StringBuilder grouped = new StringBuilder(countryCode);
430	        for (int i = 0; i < national.length(); i++) {
431	            if (i % 3 == 0) {
432	                grouped.append(' ');
433	            }
434	            grouped.append(national.charAt(i));
435	        }
436	        return grouped.toString();
437	    }
438	
439	    /** The recognised telephone country code that {@code telephone} begins with (e.g. {@code "+61"}),
440	     *  or {@code null} when it is {@code null} or begins with no recognised country code. */
441	    public static String countryCodeOf(String telephone) {
442	        if (telephone == null) {
443	            return null;
444	        }
445	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
446	            if (telephone.startsWith(countryCode)) {
447	                return countryCode;
448	            }
449	        }
450	        return null;
451	    }
452	
453	    /** The national-number length required for {@code countryCode}, or {@code null} when the country
454	     *  code carries no length rule (i.e. any code absent from the table: {@code +61 => 9},
455	     *  {@code +1 => 10}). */
456	    public static Integer nationalNumberLength(String countryCode) {
457	        return NATIONAL_NUMBER_LENGTHS.get(countryCode);
458	    }
459	
460	    /** The single Luhn check digit (0-9) over the decimal digits contained in {@code value}, scanning
461	     *  right to left and doubling every second digit; non-digit characters are ignored and a null or
462	     *  digit-free value yields {@code 0}. */
463	    private static int luhnCheckDigit(String value) {
464	        int sum = 0;
465	        boolean doubling = true;
466	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
467	            char c = value.charAt(i);
468	            if (c < '0' || c > '9') {
469	                continue;
470	            }
471	            int digit = c - '0';
472	            if (doubling) {
473	                digit *= 2;
474	                if (digit > 9) {
475	                    digit -= 9;
476	                }
477	            }
478	            sum += digit;
479	            doubling = !doubling;
480	        }
481	        return (10 - (sum % 10)) % 10;
482	    }
483	
484	    protected Set<Pet> getPetsInternal() {
485	        if (this.pets == null) {
486	            this.pets = new HashSet<>();
487	        }
488	        return this.pets;
489	    }
490	
491	    protected void setPetsInternal(Set<Pet> pets) {
492	        this.pets = pets;
493	    }
494	
495	    public List<Pet> getPets() {
496	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
497	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
498	        return Collections.unmodifiableList(sortedPets);
499	    }
500	
501	    public void setPets(List<Pet> pets) {
502	        this.pets = new HashSet<>(pets);
503	    }
504	
505	    public void addPet(Pet pet) {
506	        getPetsInternal().add(pet);
507	        pet.setOwner(this);
508	    }
509	
510	    /**
511	     * Return the Pet with the given name, or null if none found for this Owner.
512	     *
513	     * @param name to test
514	     * @return true if pet name is already in use
515	     */
516	    public Pet getPet(String name) {
517	        return getPet(name, false);
518	    }
519	
520	    /**
521	     * Return the Pet with the given name, or null if none found for this Owner.
522	     *
523	     * @param name to test
524	     * @return true if pet name is already in use
525	     */
526	    public Pet getPet(String name, boolean ignoreNew) {
527	        name = name.toLowerCase();
528	        for (Pet pet : getPetsInternal()) {
529	            if (!ignoreNew || !pet.isNew()) {
530	                String compName = pet.getName();
531	                compName = compName.toLowerCase();
532	                if (compName.equals(name)) {
533	                    return pet;
534	                }
535	            }
536	        }
537	        return null;
538	    }
539	
540	    public Pet getPet(Integer petId) {
541	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
542	    }
543	
544	    @Override
545	    public String toString() {
546	        return new ToStringCreator(this)
547	
548	            .append("id", this.getId())
549	            .append("new", this.isNew())
550	            .append("lastName", this.getLastName())
551	            .append("firstName", this.getFirstName())
552	            .append("address", this.address)
553	            .append("city", this.city)
554	            .append("telephone", this.telephone)
555	            .toString();
556	    }
557	}
