246	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
247	    @Override
248	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
249	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
250	        if (currentOwner == null) {
251	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
252	        }
253	        currentOwner.setAddress(ownerFieldsDto.getAddress());
254	        currentOwner.setCity(ownerFieldsDto.getCity());
255	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
256	        currentOwner.setLastName(ownerFieldsDto.getLastName());
257	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
258	        String email = ownerFieldsDto.getEmail();
259	        if (email != null) {
260	            email = email.trim().toLowerCase(Locale.ROOT);
261	            if (!EMAIL_PATTERN.matcher(email).matches()) {
262	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
263	            }
264	        }
265	        currentOwner.setEmail(email);
266	        this.clinicService.saveOwner(currentOwner);
267	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
268	    }
