344	
345	    /** Matches a well-formed postcode: exactly 4 digits. */
346	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
347	
348	    /**
349	     * Whether {@code owner}'s postcode is acceptable. Postcode is optional: a null postcode is always
350	     * accepted. When present it must be a 4-digit value and, when the owner's city maps to a known
351	     * region, must fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099,
352	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode. The region-to-range
353	     * table lives on {@link Owner#postcodeRangeForRegion(String)} and is shared, not duplicated here.
354	     */
355	    private static boolean isPostcodeValidForCity(Owner owner) {
356	        String postcode = owner.getPostcode();
357	        if (postcode == null) {
358	            return true;
359	        }
360	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
361	            return false;
362	        }
363	        int[] range = Owner.postcodeRangeForRegion(owner.getRegion());
364	        if (range == null) {
365	            return true;
366	        }
367	        int value = Integer.parseInt(postcode);
368	        return value >= range[0] && value <= range[1];
369	    }
370	
371	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
372	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
373	
374	    /**
375	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
376	     * code are kept when present; otherwise country code '+61' is assumed and a single
377	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
378	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
379	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
380	     * Returns {@code null} when the number cannot form a valid E.164 value.
381	     */
382	    private static String normalizeTelephone(String telephone) {
383	        if (telephone == null) {
384	            return null;
385	        }
386	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
387	        String e164;
388	        if (cleaned.startsWith("+")) {
389	            e164 = cleaned;
390	        } else {
391	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
392	            e164 = "+61" + national;
393	        }
394	        if (!E164_PATTERN.matcher(e164).matches()) {
395	            return null;
396	        }
397	        return hasValidNationalNumberLength(e164) ? e164 : null;
398	    }
399	
400	    /**
401	     * Whether the national number of a well-formed E.164 value has the length required for its
402	     * country code. The country-code length table lives on {@link Owner#nationalNumberLength(String)}
403	     * and is shared, not duplicated here; a country code carrying no length rule is accepted.
404	     */
405	    private static boolean hasValidNationalNumberLength(String e164) {
406	        String countryCode = Owner.countryCodeOf(e164);
407	        if (countryCode == null) {
408	            return true;
409	        }
410	        return e164.length() - countryCode.length() == Owner.nationalNumberLength(countryCode);
411	    }
412	
413	    /**
414	     * Compute and assign the derived attributes carried by a newly registered owner: the customer
415	     * code, membership number, household id, namesake count and household member count. Each is
416	     * derived from the owner's already-normalized fields and the existing owner population, so this
417	     * must run before the owner is saved, while the counts still exclude the owner being created.
418	     *
419	     * <p>{@code declaredMember} is true when the owner was created into an existing household by
420	     * setting {@code sharesHousehold}: such an owner is a declared, not a suspected, household member,
421	     * so it is never flagged as a possible duplicate; otherwise the usual possible-duplicate check
422	     * runs (and, since a create that reaches here shares no existing household, does not flag it).
423	     */
424	    private void assignRegistrationAttributes(Owner owner, boolean declaredMember) {
425	        owner.setCustomerCode(generateCustomerCode(owner));
426	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
427	        owner.setHouseholdId(householdId(owner));
428	        owner.setNamesakeCount(countNamesakes(owner));
429	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
430	        if (declaredMember) {
431	            owner.setPossibleDuplicate(false);
432	            owner.setPossibleDuplicateOf(null);
433	        } else {
434	            assignPossibleDuplicate(owner);
435	        }
436	    }
437	
438	    /**
439	     * Whether {@code owner} would join an existing household, i.e. some already-registered owner
440	     * resolves to the same {@link #householdId(Owner) householdId} (same last name and postcode).
441	     * Because the household is keyed on (last name, postcode), such a create is a household duplicate
442	     * and is rejected with {@code 409 CONFLICT} unless the request sets {@code sharesHousehold}, in
443	     * which case the owner is created as a declared household member.
444	     */
445	    private boolean hasExistingHousehold(Owner owner) {
446	        return !findHousemates(owner).isEmpty();
447	    }
448	
449	    /**
450	     * Flag {@code owner} as a possible duplicate when, though not a hard duplicate (its create having
451	     * already cleared the {@link #isDuplicate} identity gate), it shares an existing owner's last name
452	     * (compared case-insensitively with collapsed whitespace) and postcode but carries a different
453	     * telephone. Sets {@code possibleDuplicate} accordingly and, when true, {@code possibleDuplicateOf}
454	     * to the matching owner's id. Runs before save, against the existing owner population.
455	     */
456	    private void assignPossibleDuplicate(Owner owner) {
457	        Integer matchId = findPossibleDuplicateOf(owner);
458	        owner.setPossibleDuplicate(matchId != null);
459	        owner.setPossibleDuplicateOf(matchId);
460	    }
461	
462	    /**
463	     * The id of an existing owner that shares {@code owner}'s postcode and last name (compared
464	     * case-insensitively with collapsed whitespace) but has a different telephone, or {@code null}
465	     * when there is none. When several match, the lowest id is returned. An owner without a postcode
466	     * never matches.
467	     */
468	    private Integer findPossibleDuplicateOf(Owner owner) {
469	        String postcode = owner.getPostcode();
470	        if (postcode == null) {
471	            return null;
472	        }
473	        String lastName = normalizeHouseholdField(owner.getLastName());
474	        String telephone = owner.getTelephone();
475	        return this.clinicService.findAllOwners().stream()
476	            .filter(existing -> existing.getId() != null
477	                && postcode.equals(existing.getPostcode())
478	                && normalizeHouseholdField(existing.getLastName()).equals(lastName)
479	                && !telephone.equals(existing.getTelephone()))
480	            .map(Owner::getId)
481	            .min(Integer::compareTo)
482	            .orElse(null);
483	    }
484	
485	    /**
486	     * Build {@code owner}'s customer code '<REGION>-<HASH8>': REGION is the region code derived from
487	     * the owner's postcode ({@link Owner#getRegion()}) and HASH8 the first 8 upper-case hex
488	     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
489	     * owner's last name (e.g. 'NSW-1A2B3C4D'). The identity is otherwise a pure function of the
490	     * region and the (telephone, last name) pair; only when the computed code collides with an
491	     * existing owner's customer code is it de-duplicated by appending '-<n>' with the smallest
492	     * {@code n} of 2 or more that makes it unique (e.g. 'NSW-1A2B3C4D-2').
493	     */
494	    private String generateCustomerCode(Owner owner) {
495	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
496	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
497	        String hash8 = sha256Hex(telephone + lastName).substring(0, 8);
498	        String base = owner.getRegion() + "-" + hash8;
499	        return deduplicateCustomerCode(base);
500	    }
501	
502	    /**
503	     * De-duplicate a computed customer code against the existing owner population: when {@code base}
504	     * is not already in use it is returned unchanged; otherwise '-<n>' is appended with the smallest
505	     * {@code n} of 2 or more that yields a code no existing owner carries.
506	     */
507	    private String deduplicateCustomerCode(String base) {
508	        Set<String> existing = this.clinicService.findAllOwners().stream()
509	            .map(Owner::getCustomerCode)
510	            .filter(code -> code != null)
511	            .collect(java.util.stream.Collectors.toSet());
512	        if (!existing.contains(base)) {
513	            return base;
514	        }
515	        int n = 2;
516	        while (existing.contains(base + "-" + n)) {
517	            n++;
518	        }
519	        return base + "-" + n;
520	    }
521	
522	    /**
523	     * The number of existing owners registered in {@code city}, compared case-insensitively
524	     * with collapsed whitespace.
525	     */
526	    private int countOwnersInCity(String city) {
527	        String normalized = normalizeHouseholdField(city);
528	        return (int) this.clinicService.findAllOwners().stream()
529	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
530	            .count();
531	    }
532	
533	    /**
534	     * The effective registration date to store for a new owner: the date supplied on the request
535	     * when present, otherwise the current server date, in either case rolled forward to a business
536	     * day so it never falls on a weekend (a Saturday or Sunday is advanced to the following Monday).
537	     * This single point of resolution is what every registration-date-derived value (the stored
538	     * date, the membership number's year segment, the per-day create-limit) is computed from.
539	     */
540	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
541	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
542	        return toBusinessDay(date);
543	    }
544	
545	    /**
546	     * Roll {@code date} forward to the next business day: a Saturday or Sunday is advanced to the
547	     * following Monday; a weekday is returned unchanged.
548	     */
549	    private static LocalDate toBusinessDay(LocalDate date) {
550	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
551	            date = date.plusDays(1);
552	        }
553	        return date;
554	    }
555	
556	    /**
557	     * Build the membership number '<customerCode>-M<YY>' where YY is the last two digits of the
558	     * {@code registrationDate} year (e.g. 'NSW-1A2B3C4D-M26').
559	     */
560	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
561	        String yy = String.format("%02d", registrationDate.getYear() % 100);
562	        return customerCode + "-M" + yy;
563	    }
564	
565	    /**
566	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
567	     * last name, compared case-insensitively.
568	     */
569	    private int countNamesakes(Owner owner) {
570	        String firstName = normalizeHouseholdField(owner.getFirstName());
571	        String lastName = normalizeHouseholdField(owner.getLastName());
572	        return (int) this.clinicService.findAllOwners().stream()
573	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
574	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
575	            .count();
576	    }
577	
578	    /**
579	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
580	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
581	     * unusually high daily signup volume.
582	     */
583	    private boolean isBulkSignupWarning() {
584	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
585	    }
586	
587	    /** The number of existing owners whose registration date is {@code date}. */
588	    private int countOwnersRegisteredOn(LocalDate date) {
589	        return (int) this.clinicService.findAllOwners().stream()
590	            .filter(existing -> date.equals(existing.getRegistrationDate()))
591	            .count();
592	    }
593	
594	    /**
595	     * The single derived key all duplicate detection flows through, formed from the owner's
596	     * already-normalized fields as {@code normalizedTelephone + '|' + (email or empty) + '|' +
597	     * (householdId or empty)}. It is computed at the create-time identity gate, before the household
598	     * id is derived, so the household segment is empty at that point. Because the telephone is part
599	     * of the key, two owners in the same household with different telephones resolve to different
600	     * keys and are both allowed.
601	     */
602	    private static String identityKey(Owner owner) {
603	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
604	        String email = owner.getEmail() == null ? "" : owner.getEmail();
605	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
606	        return telephone + "|" + email + "|" + household;
607	    }
608	
609	    /**
610	     * Whether {@code owner}'s whole {@link #identityKey} equals an existing owner's, which is the sole
611	     * duplicate condition: the previously separate telephone, email and household checks are now all
612	     * expressed through this one key, so only an exact full-key match is a duplicate and a create that
613	     * trips it is rejected with {@code 409 CONFLICT}.
614	     */
615	    private boolean isDuplicate(Owner owner) {
616	        String key = owner.getIdentityKey();
617	        return this.clinicService.findAllOwners().stream()
618	            .map(Owner::getIdentityKey)
619	            .filter(existing -> existing != null)
620	            .anyMatch(key::equals);
621	    }
622	
623	    /** Common street-type abbreviations expanded during address normalization. */
624	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
625	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
626	
627	    /**
628	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
629	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
630	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
631	     * string when {@code address} is null or blank after normalization.
632	     */
633	    private static String normalizeAddress(String address) {
634	        if (address == null) {
635	            return "";
636	        }
637	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
638	        if (collapsed.isEmpty()) {
639	            return "";
640	        }
641	        StringBuilder sb = new StringBuilder(collapsed.length());
642	        for (String token : collapsed.split(" ")) {
643	            if (sb.length() > 0) {
644	                sb.append(' ');
645	            }
646	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
647	        }
648	        return sb.toString();
649	    }
650	
651	    /**
652	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
653	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
654	     */
655	    private static String normalizeHouseholdField(String value) {
656	        if (value == null) {
657	            return "";
658	        }
659	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
660	    }
661	
662	    /**
663	     * Existing owners that share {@code owner}'s household, i.e. resolve to the same
664	     * {@link #householdId(Owner) householdId}. Household membership is defined by that single derived
665	     * key rather than re-derived from the underlying fields here, so the household is described in one
666	     * place and every household-keyed value stays consistent with it.
667	     */
668	    private List<Owner> findHousemates(Owner owner) {
669	        String householdId = householdId(owner);
670	        return this.clinicService.findAllOwners().stream()
671	            .filter(existing -> householdId(existing).equals(householdId))
672	            .toList();
673	    }
674	
675	    /**
676	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
677	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
678	     */
679	    private int countHouseholdMembers(Owner owner) {
680	        return findHousemates(owner).size() + 1;
681	    }
682	
683	    /**
684	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
685	     * same last name (compared case-insensitively with collapsed whitespace) and postcode. It is the
686	     * first 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode} (the empty
687	     * string standing in for a missing postcode), so housemates always resolve to the same value
688	     * regardless of registration order, and owners sharing a last name and postcode share it
689	     * automatically.
690	     */
691	    private static String householdId(Owner owner) {
692	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
693	        String key = normalizeHouseholdField(owner.getLastName()) + "|" + postcode;
694	        return sha256Hex(key).substring(0, 12);
695	    }
696	
697	    /** The upper-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters. */
698	    private static String sha256Hex(String input) {
699	        try {
700	            byte[] digest = MessageDigest.getInstance("SHA-256")
701	                .digest(input.getBytes(StandardCharsets.UTF_8));
702	            StringBuilder sb = new StringBuilder(digest.length * 2);
703	            for (byte b : digest) {
704	                sb.append(String.format("%02X", b));
705	            }
706	            return sb.toString();
707	        }
708	        catch (NoSuchAlgorithmException e) {
709	            throw new IllegalStateException("SHA-256 not available", e);
710	        }
711	    }
712	}
